def obter_conteudo_plano_referencia(nome_disciplina):
    # O cadastro pode conter acentos diferentes e sufixos como "(60h)".
    import re
    import unicodedata

    def normalizar(valor):
        texto = unicodedata.normalize("NFKD", str(valor or "")).casefold()
        texto = "".join(c for c in texto if not unicodedata.combining(c))
        texto = re.sub(r"\\b60\\s*(?:h|horas)\\b", " ", texto)
        texto = re.sub(r"[^a-z0-9]+", " ", texto)
        return " ".join(texto.split())

    nome = normalizar(nome_disciplina)
    entradas = {normalizar(k): v for k, v in PLANOS_REFERENCIA_60H.items()}
    entradas["quimica geral experimental"] = entradas["quimica geral e experimental"]
    entrada = entradas.get(nome)
    if entrada is None:
        return None
    unidades = [
        {"titulo": f"UNIDADE {i} — {u[0]}", "topicos": list(u[1])}
        for i, u in enumerate(entrada["unidades"], 1)
    ]
    assert len(unidades) == 8, "O plano institucional exige pelo menos 8 unidades"
    conteudo = "\n\n".join(
        u["titulo"] + "\n" + "\n".join(f"• {t}" for t in u["topicos"])
        for u in unidades
    )
    return {
        "objetivo_geral": entrada["objetivo_geral"],
        "objetivos_especificos": " ".join(f"{i}. {t}" for i,t in enumerate(entrada["objetivos_especificos"],1)),
        "ementa_expandida": entrada["ementa"],
        "conteudo_programatico": conteudo,
        "conteudo_programatico_estruturado": unidades,
        "habilidades": " ".join(f"{i}. {t}" for i,t in enumerate(entrada["habilidades"],1)),
        "bibliografia_basica": "\n".join(entrada["bas"]),
        "bibliografia_complementar": "\n".join(entrada["comp"]),
        "pre_requisitos": entrada["pre_requisitos"],
        "enquadramento_curricular": entrada["enquadramento_curricular"],
        "modalidade": entrada["modalidade"],
        "numero_unidades": 8,
    }
